previewCss:
.darma-loader-sine-wave-trace {
  position: relative;
  width: 52px;
  height: 36px;
}
.darma-loader-sine-wave-trace::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 0;
  right: 0;
  height: 2px;
  margin-top: -1px;
  border-radius: 2px;
  background: #c7d2fe;
}
.darma-loader-sine-wave-trace i {
  position: absolute;
  top: 50%;
  left: 0;
  width: 10px;
  height: 10px;
  margin-top: -5px;
  border-radius: 50%;
  background: var(--loader-color, #6366f1);
  animation: darma-loader-sine-wave-trace-sx 1.6s linear infinite alternate, darma-loader-sine-wave-trace-sy 0.8s ease-in-out infinite;
}
@keyframes darma-loader-sine-wave-trace-sx {
  from { left: 0; }
  to { left: calc(100% - 10px); }
}
@keyframes darma-loader-sine-wave-trace-sy {
  0%, 100% { transform: translateY(-11px); }
  50% { transform: translateY(11px); }
}

